// Mod registry, MOD0: bundled trusted mods only, in-process (village-mods.md §2.3, §6.1.1). OWNER: A1.
// The sandbox (MOD-2) and data packs (MOD-5) plug in here later; nothing outside engine/mod/ knows where a mod came from.
import { API_VERSION, FEATURES } from './api.js';
import { hash, streamFor } from '../core/rng.js';
import { checkClasses } from './kit/terrain.js';
// The bundled mods (mods/index.js, generated by `npm run mods`: tools/mods-index.mjs). The only engine → mods/** import.
import BUNDLED_MODS from '../../../../mods/index.js';

export const DEFAULT_MOD = 'agentville.fantasy';

// Mod ids are reverse-DNS. A trailing `.demo` is reserved: va.engine2.world.<id>.demo is another mod's demo persistence key.
export const MOD_ID_RE = /^[a-z0-9]+(\.[a-z0-9][a-z0-9-]*)+$/;
export function validateModId(id) {
  if (typeof id !== 'string' || id.length > 64 || !MOD_ID_RE.test(id) || id.endsWith('.demo'))
    throw new Error(`invalid mod id ${JSON.stringify(String(id)).slice(0, 80)}: must be reverse-DNS (${MOD_ID_RE}), at most 64 characters, and must not end in ".demo"`);
  return id;
}
const FIRST_PARTY = id => typeof id === 'string' && id.startsWith('agentville.');
const idProblem = id => { try { validateModId(id); return null; } catch (e) { return e.message; } };
/** Indexes a list of mods by id. A mod with an invalid or a duplicate id is skipped with a { kind, mod, reason } lint
 *  record, never thrown: one bad folder must not break every world. */
export function indexMods(list) {
  const byId = new Map(), lint = [];
  for (const m of Array.isArray(list) ? list : []) {
    const id = m?.id, bad = m && typeof m === 'object' ? idProblem(id) : 'not a mod object';
    if (bad) lint.push({ kind: 'mod-id', mod: String(id).slice(0, 80), reason: `skipped: ${bad}` });
    else if (byId.has(id)) lint.push({ kind: 'mod-duplicate', mod: id, reason: `skipped: a second mod with id "${id}" (the first one is kept)` });
    else byId.set(id, m);
  }
  return { byId, lint: Object.freeze(lint.map(Object.freeze)) };
}
const REGISTRY = indexMods(BUNDLED_MODS), BUNDLED = REGISTRY.byId;
/** Problems found indexing the bundled mods (skipped invalid or duplicate ids). */
export function registryLint() { return REGISTRY.lint; }
export const DATA_KEYS = ['rules', 'terrain', 'objects', 'behaviour', 'represent', 'venues'];

const isPlain = v => v && typeof v === 'object' && !Array.isArray(v) && Object.getPrototypeOf(v) === Object.prototype;
/** Data merge: objects merge key by key, arrays and everything else replace (the child wins). */
export function mergeData(parent, child) {
  if (child === undefined) return parent;
  if (!isPlain(parent) || !isPlain(child)) return child;
  const out = { ...parent };
  for (const [k, v] of Object.entries(child)) out[k] = mergeData(parent[k], v);
  return out;
}
/** represent.pr merges per PR state: a PrSpec is atomic, so a child's state entry replaces the parent's whole entry (a
 *  child's `building: { as: 'lot' }` never inherits a parent's `model`). A function table replaces the whole table. */
export function mergeModData(parent, child, key) {
  const out = mergeData(parent, child);
  if (key === 'represent' && isPlain(parent?.pr) && isPlain(child?.pr)) out.pr = { ...parent.pr, ...child.pr };
  return out;
}
const deepFreeze = o => { if (o && typeof o === 'object' && !Object.isFrozen(o)) { Object.freeze(o); for (const v of Object.values(o)) deepFreeze(v); } return o; };

/** The extends-chain of a mod in `byId`, nearest first. Throws when a parent is not there. */
function chainOf(id, byId = BUNDLED) {
  const chain = [];
  for (let m = byId.get(id); m && !chain.includes(m.id);) {
    chain.push(m.id);
    if (!m.extends) break;
    const p = byId.get(m.extends);
    if (!p) throw new Error(`mod ${m.id}: extends ${JSON.stringify(String(m.extends)).slice(0, 80)} is not a bundled mod`);
    m = p;
  }
  return chain;
}

/** Where each hook takes its ctx (api.js ModHooks). A hook not listed here, or a ctx that is not an object, passes through. */
export const CTX_AT = Object.freeze({ growth: 1, tier: 2, capacity: 2, lots: 3, crowns: 2, planSettlement: 1, style: 1, layout: 1, scatter: 2 });
const NO_HOOKS = Object.freeze({});
/** Per-level hook tables for a chain of mods (nearest first). levels[i] holds the hooks resolved from mods[i] upward; a
 *  hook defined at level j is wrapped so it sees `ctx.parent === levels[j + 1]`, never the top mod's parent, so a hook that
 *  calls ctx.parent.X at every level walks up the chain once. Wrappers are made once per level and reused by the levels
 *  below (an inherited hook is the same function object); the bound ctx is cached per level in a WeakMap keyed on the
 *  incoming ctx, so a hook run per tile (scatter) allocates one ctx per caller ctx, not per call. */
function bindLevels(mods) {
  const n = mods.length, levels = new Array(n + 1), bound = [];
  levels[n] = NO_HOOKS;
  const bindCtx = (ctx, p) => {
    const memo = bound[p] || (bound[p] = new WeakMap());
    let b = memo.get(ctx);
    if (!b) { b = { ...ctx, parent: levels[p] }; memo.set(ctx, b); }
    return b;
  };
  const wrap = (name, fn, p) => {
    // A one-mod chain (agentville.base resolved alone) keeps its own functions: modCtx already gives it parent {}.
    if (n === 1 || typeof fn !== 'function' || !Object.hasOwn(CTX_AT, name)) return fn;
    const at = CTX_AT[name];
    return function bound(...args) {
      const ctx = args[at];
      if (ctx !== null && typeof ctx === 'object') args[at] = bindCtx(ctx, p);
      return fn.apply(this, args);
    };
  };
  for (let i = n - 1; i >= 0; i--) {
    const h = { ...levels[i + 1] };
    for (const [name, fn] of Object.entries(mods[i].hooks || {})) h[name] = wrap(name, fn, i + 1);
    levels[i] = Object.freeze(h);
  }
  return levels;
}

const LEGACY_OWNER = 'agentville.fantasy';   // the bare va.engine2.world key and the classic va.world<N> keys are its own
const WORLD_KEY_PREFIX = 'va.engine2.world';
/** A PersistDecl may name only the mod's own keys: `va.engine2.world.<its id>` (+ `.demo`). The bare
 *  `va.engine2.world` and the classic `va.world<N>` keys belong to agentville.fantasy. The key shapes themselves are
 *  checked by world/persist.js checkPersist when the layout loads. Throws on a key the mod does not own. */
export function checkPersistOwner(decl, id) {
  if (decl == null || typeof decl !== 'object') return;
  const keys = [decl.key, decl.demoKey, ...(Array.isArray(decl.also) ? decl.also : []), ...(Array.isArray(decl.import) ? decl.import : [])];
  for (const k0 of keys) {
    if (typeof k0 !== 'string') continue;
    const k = k0.endsWith('.demo') ? k0.slice(0, -5) : k0;
    const legacy = k === WORLD_KEY_PREFIX || /^va\.world\d+$/.test(k);
    const other = k.startsWith(`${WORLD_KEY_PREFIX}.`) && k.slice(WORLD_KEY_PREFIX.length + 1) !== id;
    if ((legacy && id !== LEGACY_OWNER) || other)
      throw new Error(`mod ${id}: persist key ${JSON.stringify(k0).slice(0, 80)} is not this mod's (use ${WORLD_KEY_PREFIX}.${id}, or leave persist out)`);
  }
}

/** Lint for a mod's own (top) data: its terrain classes (kit/terrain.js checkClasses). Plain { kind, reason } records. */
export function lintTop(top) {
  const classes = top?.terrain?.classes;
  return classes === undefined ? [] : checkClasses(classes).map(reason => ({ kind: 'terrain-classes', mod: top.id, reason }));
}

const CACHE = new Map();
/** Resolves the extends-chain: data deep-merges (objects merge, arrays replace, represent.pr per PR state); each hook
 *  comes from the nearest mod that defines it and sees ctx.parent bound to the hooks of the level above it (bindLevels);
 *  `parentHooks` are the hooks resolved from chain[1] upward. persist is top-only. `ambient` (not in API v1) comes only
 *  from first-party agentville.* mods; another mod's own ambient is ignored with an M6 lint. Unknown id → DEFAULT_MOD.
 *  Throws on an unsupported apiVersion, a missing parent, or a persist key the mod does not own; `lint` holds problems in
 *  the mod's own data. */
export function resolveMod(id = DEFAULT_MOD) {
  validateModId(id);
  if (!BUNDLED.has(id)) id = DEFAULT_MOD;
  if (CACHE.has(id)) return CACHE.get(id);
  const resolved = resolveIn(BUNDLED, id);
  CACHE.set(id, resolved);
  return resolved;
}

/** Test and tooling seam: resolves `id` against the bundled mods plus `mods` (in-memory mod objects), uncached and with
 *  no fallback to DEFAULT_MOD. A mod in `mods` whose id is invalid or already taken is skipped (see indexMods). */
export function resolveWith(mods, id) {
  validateModId(id);
  const { byId } = indexMods([...BUNDLED.values(), ...(Array.isArray(mods) ? mods : [])]);
  if (!byId.has(id)) throw new Error(`no mod ${JSON.stringify(id)}`);
  return resolveIn(byId, id);
}

function resolveIn(byId, id) {
  const chain = chainOf(id, byId), mods = chain.map(c => byId.get(c));
  const top = mods[0];
  if (top.apiVersion !== API_VERSION) throw new Error(`mod ${id}: apiVersion ${top.apiVersion} is not supported (engine ${API_VERSION})`);
  checkPersistOwner(top.persist, top.id);
  const data = {};
  for (const m of [...mods].reverse()) for (const k of DATA_KEYS) data[k] = mergeModData(data[k], m[k], k);
  const levels = bindLevels(mods);
  const lint = lintTop(top);
  // ambient is code and not in API v1: inherited from first-party mods only (trusted bundled code until the MOD-2 sandbox).
  if (top.ambient != null && !FIRST_PARTY(top.id))
    lint.push({ kind: 'ambient', rule: 'M6', mod: top.id, reason: 'M6 ambient is not in the v1 mod API; this mod\'s own `ambient` is ignored' });
  const resolved = {
    id: top.id, name: top.name, version: top.version, apiVersion: top.apiVersion, chain,
    rules: data.rules, terrain: data.terrain, objects: data.objects,
    behaviour: data.behaviour, represent: data.represent, venues: data.venues,
    ambient: mods.find(m => m.ambient && FIRST_PARTY(m.id))?.ambient ?? null,
    hooks: levels[0], parentHooks: levels[1],
    // persist is top-only: a child of fantasy never inherits its legacy keys (PersistDecl, api.js).
    persist: top.persist ?? null,
    lint: Object.freeze(lint),
  };
  // byName is derived when a terrain table omits it.
  if (resolved.terrain && !resolved.terrain.byName) resolved.terrain = { ...resolved.terrain, byName: Object.fromEntries((resolved.terrain.types || []).map(t => [t.name, t.code])) };
  deepFreeze(resolved.rules); deepFreeze(resolved.terrain); deepFreeze(resolved.objects); deepFreeze(resolved.behaviour); deepFreeze(resolved.represent); deepFreeze(resolved.venues); deepFreeze(resolved.persist);
  return resolved;
}

/** ModCtx for one project: rng(stream) is streamFor(world seed, mod id, project key, stream). */
export function modCtx(mod, { seed = 0, now = 0, projectKey = '', forcedTier = null, forcedStyle = null } = {}) {
  return {
    rng: stream => streamFor(seed, mod.id, projectKey, stream),
    hash, time: { now }, forcedTier, forcedStyle,
    parent: mod.parentHooks || null,
    api: { version: API_VERSION, has: f => FEATURES.includes(f) },
  };
}

export function listMods() {
  return [...BUNDLED.values()].map(m => ({ id: m.id, name: m.name, version: m.version, apiVersion: m.apiVersion, kind: 'code', extends: m.extends || null, source: 'bundled' }));
}
